<form class="filters" method="get"><input name="q" value="<?= e($filters['q']) ?>" placeholder="<?= e(__('actions.search')) ?>"><select name="status"><option value=""><?= e(__('fields.status')) ?></option><?php foreach ($statuses as $status): ?><option value="<?= e($status['code']) ?>" <?= selected($filters['status'], $status['code']) ?>><?= e($status['name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary" type="submit"><?= e(__('actions.filter')) ?></button><a class="btn btn-ghost" href="<?= e(url('/admin/cases/create')) ?>"><?= e(__('admin.new_case')) ?></a></form>
<?php if ($page['rows'] === []): ?><p class="empty"><?= e(__('empty.results')) ?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(__('fields.number')) ?></th><th><?= e(__('admin.customers')) ?></th><th><?= e(__('fields.status')) ?></th><th><?= e(__('fields.date')) ?></th></tr></thead><tbody><?php foreach ($page['rows'] as $row): ?><tr><td data-label="Number"><a href="<?= e(url('/admin/cases/' . $row['id'])) ?>"><?= e($row['number']) ?></a></td><td data-label="Customer"><?= e($row['customer_name']) ?></td><td data-label="Status"><?= status_badge($row['status_name'] ?: $row['status_code'], $row['badge_tone']) ?></td><td data-label="Date"><?= e(format_date($row['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?= paginator($page, '/admin/cases') ?><?php endif; ?>
